private static void readSingle(String aLine,Map<String,Point> mapping) throws IOException {
  try {
    StringTokenizer tokens=new StringTokenizer(aLine,"",false);
    String name=tokens.nextToken("(").trim();
    if (mapping.containsKey(name))   throw new IOException("name found twice:" + name);
    int x=Integer.parseInt(tokens.nextToken("(, "));
    int y=Integer.parseInt(tokens.nextToken(",) "));
    Point p=new Point(x,y);
    mapping.put(name,p);
  } catch (NoSuchElementException | NumberFormatException e) {
    throw new IOException("Invalid input format: " + aLine, e);
  }
}
